/* Подмешиваем к гексаграммам, чтобы движок читал их как HEX[n].lines */
if (typeof module !== "undefined" && typeof require !== "undefined") {
  const D = require("./data.js");
  for (const n in HEX_LINES) if (D.HEX[n]) D.HEX[n].lines = HEX_LINES[n];
  module.exports = HEX_LINES;
} else {
  for (const n in HEX_LINES) if (typeof HEX !== "undefined" && HEX[n]) HEX[n].lines = HEX_LINES[n];
}
